  void UpdateMapLayer();          // 매 프레임: 내 위치 표시, 다른 창이 열리면 지도 위젯을 통째로 숨김
  bool mapOpen=false,mapShown=true;float mapLeft=0,mapTop=0,mapScale=1,mapMinX=0,mapMaxY=0;
