  void UiPosition(const std::string& n,hb::Vec2 v){v={std::round(v.x),std::round(v.y)};if(UiChanged("p"+n,UiNum(v.x,v.y)))hb::UI::SetPosition(UiOwnerOf(n),UiInstance(n),n,v);}
